INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11501, 'Nehemiah 4:12', 'Nehemiah', 4, 12, '&nbsp;خو چې زمونږ د دشمنانو سره کوم يهوديان اوسېدل هغوئ وخت په وخت راتلل او چې زمونږ دشمنانو زمونږ خِلاف کومې منصوبې جوړولې نو د هغې نه به يې خبرولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11502, 'Nehemiah 4:13', 'Nehemiah', 4, 13, '&nbsp;نو ما خلقو له تُورې، نېزې او غشى ورکړل او قبيله په قبيله مې د دېوال شاته په هغه ځايونو کښې ودرول چرته چې کار لا ختم شوے نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11503, 'Nehemiah 4:14', 'Nehemiah', 4, 14, '&nbsp;ما ته پته ولګېده چې خلق يرېدلى وُو، نو ما هغوئ، او د هغوئ مشرانو او آفسرانو ته ووئيل، ”زمونږ د دشمنانو نه مۀ يرېږئ. ياد ساتئ چې مالِک خُدائ ډېر لوئ او يروونکے دے او ستاسو وطندارانو، ستاسو زامنو، لوڼو، ښځو او ستاسو د کورونو دپاره جنګ وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11504, 'Nehemiah 4:15', 'Nehemiah', 4, 15, '&nbsp;زمونږ دشمنان خبر شول چې مونږ ته دا پته لګېدلې ده چې هغوئ څۀ منصوبه جوړوله او چې خُدائ پاک د هغوئ منصوبې خرابې کړې دى. نو مونږ ټول د دېوال د بيا جوړولو دپاره واپس روان شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11505, 'Nehemiah 4:16', 'Nehemiah', 4, 16, '&nbsp;د هغه وخت نه واخله زما نيمو سړو به کار کولو او نيم کسان به د څوکيدارۍ دپاره ولاړ وُو. هغوئ زغرې اغوستې وې او نېزې، ډالونه او غشى ورسره وُو. او زمونږ مشرانو د خلقو سره پوره مدد کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11506, 'Nehemiah 4:17', 'Nehemiah', 4, 17, '&nbsp;يعنې د هغه خلقو سره چا چې دېوال جوړولو. چې کومو کسانو به د عمارت سامان وړلو نو هغوئ به هم په يو لاس باندې کار کولو او په بل لاس کښې به يې وسله نيولې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11507, 'Nehemiah 4:18', 'Nehemiah', 4, 18, '&nbsp;او هر چا به چې د جوړولو کار کولو نو هر يو به په خپله ملا پورې تُوره تړلې وه خو چې کوم سړى به د خبردارى دپاره بيګل غږولو نو هغه به ما سره ايسارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11508, 'Nehemiah 4:19', 'Nehemiah', 4, 19, '&nbsp;ما خلقو، د هغوئ آفسرانو او مشرانو ته ووئيل، ”دا کار په دومره ډېره فاصله باندې خور دے چې مونږ په دېوال باندې د يو بل نه ډېر زيات لرې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11509, 'Nehemiah 4:20', 'Nehemiah', 4, 20, '&nbsp;کۀ تاسو د بيګل آواز واورئ، نو ما ته راغونډ شئ. زمونږ خُدائ پاک به زمونږ دپاره جنګ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11510, 'Nehemiah 4:21', 'Nehemiah', 4, 21, '&nbsp;نو هره ورځ، د سحر نه واخله د شپې تر هغه وخته پورې چې ستورى به راښکاره شول، زمونږ نيمو کسانو به کار کولو، خو هغه نور نيم به د نېزو سره د څوکيدارۍ دپاره ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11511, 'Nehemiah 4:22', 'Nehemiah', 4, 22, '&nbsp;په هغه وخت کښې ما هغه مشرانو سړو ته ووئيل چې هغوئ او د هغوئ ټول مدد کوونکى به د شپې په يروشلم کښې ايساريږى، نو چې داسې مونږ د شپې د ښار څوکيدارى کوُو او د ورځې به کار کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11512, 'Nehemiah 4:23', 'Nehemiah', 4, 23, '&nbsp;ما د شپې هم خپلې جامې نۀ ويستلې، نۀ زما ملګرو، نۀ زما خِدمتګارانو او نۀ زما څوکيدارانو ويستلې. او کۀ مونږ د اوبو دپاره هم تلو نو مونږ ټولو به وسله د ځان سره ساتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11513, 'Nehemiah 5:1', 'Nehemiah', 5, 1, '&nbsp;څۀ موده وروستو ډېرو سړو او ښځو، د خپلو يهوديانو خِلاف شکايت شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11514, 'Nehemiah 5:2', 'Nehemiah', 5, 2, '&nbsp;څۀ کسانو ووئيل، ”زمونږ خاندان غټ شوے دے او د ژوندى پاتې کېدو دپاره مونږ ته د خوراک ضرورت دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11515, 'Nehemiah 5:3', 'Nehemiah', 5, 3, '&nbsp;څۀ کسانو ووئيل، ”مونږ خپل پټى، د انګورو باغونه او خپل کورونه د دې دپاره ګاڼه کړى دى چې د قحط په وخت کښې راته کافى خوراک مِلاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11516, 'Nehemiah 5:4', 'Nehemiah', 5, 4, '&nbsp;خو څۀ کسانو دا هم ووئيل، ”مونږ پېسې قرض کړې وې چې په خپلو پټو او د انګورو په باغونو مو بادشاه له محصُول ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11517, 'Nehemiah 5:5', 'Nehemiah', 5, 5, '&nbsp;مونږ يهوديان د يو نسل نه يُو. ولې زمونږ بچى د هغوئ د بچو په شان نۀ دى؟ خو بيا هم مونږ مجبور يُو چې د خپلو بچو نه غلامان جوړوُو. زمونږ څۀ لوڼه د وړاندې نه د وينځو په توګه خرڅې شوې دى. مونږ په دې وجه بې‌مددګاره يُو چې زمونږ پټى او د انګورو باغونه زمونږ نه اخستے شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11518, 'Nehemiah 5:6', 'Nehemiah', 5, 6, '&nbsp;کله چې ما د هغوئ شکايتونه واورېدل، نو زۀ غصه شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11519, 'Nehemiah 5:7', 'Nehemiah', 5, 7, '&nbsp;په دې باندې د سوچ کولو نه پس، ما د خلقو مشران او آفسران ورټل او ورته مې ووئيل، ”تاسو د خپلو خلقو نه سود اخلئ.“ نو ما د دې دپاره د خلقو يو جرګه راوغوښته چې د دې مسئلې حل راوباسو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11520, 'Nehemiah 5:8', 'Nehemiah', 5, 8, '&nbsp;او ورته مې ووئيل، ”زمونږ چې څومره وس وى نو مونږ خپل هغه يهودى خپلوان واپس اخلو کومو چې خپل ځانونه په غېرو خلقو باندې خرڅ کړى دى. خو اوس تاسو خپل رشته‌داران او خپل خلق دې ته مجبوروئ چې خپل ځانونه په تاسو باندې خرڅ کړى.“ مشران خاموش ولاړ وُو او د وئيلو دپاره ورسره هيڅ هم نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11521, 'Nehemiah 5:9', 'Nehemiah', 5, 9, '&nbsp;بيا ورته ما ووئيل، ”تاسو چې څۀ کوئ دا ټيک نۀ دى. په کار دى چې تاسو زمونږ د خُدائ پاک نه په يره کښې ژوند تېر کړئ نو چې مونږ د غېرو قومونو د دشمنانو د پېغور نه خپل ځانونه بچ کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11522, 'Nehemiah 5:10', 'Nehemiah', 5, 10, '&nbsp;ما خلق دې ته پرېښى دى چې زما نه پېسه او غله قرض واخلى او هم زما د ملګرو او خلقو نه چې زما دپاره کار کوى. نو راځئ چې دا سود اخستل بند کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11523, 'Nehemiah 5:11', 'Nehemiah', 5, 11, '&nbsp;نو تاسو به نن خامخا هغوئ له د هغوئ پټى، د انګورو باغونه، د زيتُونو ونې او د هغوئ کورونه واپس ورکوئ. او لکه کله چې مو پېسې، غله، د انګورو نوى مے او د زيتُونو تېل قرض ورکول او چې کوم سود مو ترې نه اخستے دے هغه واپس ورکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11524, 'Nehemiah 5:12', 'Nehemiah', 5, 12, '&nbsp;مشرانو ورته ووئيل، ”تا چې څۀ ووئيل مونږ به هغه هم دغه شان وکړُو. مونږ به جائيدادونه واپس کړُو او د قرض د راغونډولو کوشش به نۀ کوُو.“ نو ما اِمامان راوغوښتل او د هغوئ په مخکښې مې د مشرانو نه دا قسم واخستلو چې هغوئ اوس اوس کومه وعده وکړه نو هغه به پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11525, 'Nehemiah 5:13', 'Nehemiah', 5, 13, '&nbsp;نو ما خپله لمن وڅنډله او ومې وئيل، ”کۀ تاسو دا وعده پوره نۀ کړه، نو خُدائ پاک دې تاسو د خپلو کورونو او خپلو جائيدادونو نه داسې وڅنډى.“ نو ټولو خلقو په جواب کښې ووئيل، ”آمين“ او هغوئ د مالِک خُدائ ثناء صِفت وکړو. او خلقو هم هغه شان وکړل چې څنګه يې وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11526, 'Nehemiah 5:14', 'Nehemiah', 5, 14, '&nbsp;په هغه ټولو دولسو کالو کښې چې زۀ د يهوداه د مُلک حکمران وم، د ارتخششتا د سلطنت د شلم کال نه د هغۀ د بادشاهۍ د دوه دېرشم کال پورې، نۀ ما او نۀ زما خپلوانو هغه خوراک خوړلے دے چې کوم د حکمران دپاره مقرر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11527, 'Nehemiah 5:15', 'Nehemiah', 5, 15, '&nbsp;زما نه مخکښې به چې کوم يو حکمران هم په دفتر کښې وو هغه به په خلقو بوج وو. د ميو او د خوراک دپاره به يې هره ورځ ترې نه څلوېښت د سپينو زرو سيکې غوښتې. د هغوئ نوکرانو به هم د خلقو سره زياتے کولو. خو ما به د هغوئ په شان کار نۀ کولو، ځکه چې زۀ د خُدائ پاک نه يرېدلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11528, 'Nehemiah 5:16', 'Nehemiah', 5, 16, '&nbsp;ما خپل ځان د دېوال د بيا جوړولو دپاره وقف کړے وو او هيڅ جائيداد مې نۀ اخستلو. هر چا چې زما دپاره کار کولو نو هغه د دېوال په بيا جوړېدو کښې شريک وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11529, 'Nehemiah 5:17', 'Nehemiah', 5, 17, '&nbsp;ما به د خپل دسترخوان نه هره ورځ يو نيم سل يهوديانو او د هغوئ مشرانو له روټۍ ورکوله. دا د هغه ټولو خلقو نه علاوه وُو کوم چې د ګېرچاپېره مُلکونو نه ما له راغلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11530, 'Nehemiah 5:18', 'Nehemiah', 5, 18, '&nbsp;هره ورځ به مې يو غوَيے، شپږ ښۀ ګډان او ډېرې چرګې تيارولې او په هره لسمه ورځ مې د انګورو د تازه ميو بندوبست کولو. خو بيا هم ما هغه پېسې نۀ غوښتلې کومې چې د حکمران دپاره مقررې وې، ځکه چې خلقو ډېر دروند بوج برداشت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11531, 'Nehemiah 5:19', 'Nehemiah', 5, 19, '&nbsp;نو اے خُدايه پاکه، زۀ ستا نه سوال کوم چې زما هغه هر يو کار ياد ساته چې ما د دې خلقو دپاره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11532, 'Nehemiah 6:1', 'Nehemiah', 6, 1, '&nbsp;سنبلط، طوبياه، عربى جشم او زمونږ نور دشمنان خبر شول چې مونږ د دېوال جوړول ختم کړى دى او چې په دې کښې يو مات ځائ هم پاتې نۀ دے، اګر چې مونږ د دروازو په ځايونو کښې دروازې هم لا نۀ وې لګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11533, 'Nehemiah 6:2', 'Nehemiah', 6, 2, '&nbsp;نو سنبلط او جشم ما له يو پېغام راولېږلو، دا مشوره يې راکوله چې د اونو په مېدان کښې په يو کلى کښې زۀ د هغوئ سره مِلاو شم. خو ما ته پته ولګېده چې دا ما ته د هغوئ د نقصان رسولو يوه منصوبه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11534, 'Nehemiah 6:3', 'Nehemiah', 6, 3, '&nbsp;ما هغوئ له پېغام وړُونکى ولېږل چې ورته ووائى، ”زۀ يو اهم کار کوم او لاندې نۀ شم درتلے. صِرف تاسو سره مِلاوېدو دپاره خپل کار نۀ شم بندولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11535, 'Nehemiah 6:4', 'Nehemiah', 6, 4, '&nbsp;هغوئ څلور ځلې ما له هم دغه پېغام رالېږلو او هر ځل ما هغوئ له هم دغه جواب ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11536, 'Nehemiah 6:5', 'Nehemiah', 6, 5, '&nbsp;بيا سنبلط خپل يو نوکر ما له د پينځم پېغام سره راولېږلو، دا د خط په شکل کښې وو او دا خط کولاو وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11537, 'Nehemiah 6:6', 'Nehemiah', 6, 6, '&nbsp;ما ولوستلو، ”جشمه ووئيل چې په ګاونډيانو کښې دا افواه خوره ده چې تۀ او يهوديان د بغاوت اراده لرئ نو دا ځکه تاسو دا دېوال بيا جوړَوئ. هغۀ دا هم ووئيل چې ستا منصوبه دا ده چې خپل ځان بادشاه کړې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11538, 'Nehemiah 6:7', 'Nehemiah', 6, 7, '&nbsp;او تا د يو څو پېغمبرانو بندوبست کړے دے چې په يروشلم کښې دا اِعلان وکړى چې تۀ د يهوداه بادشاه يې. خو بادشاه سلامت به يقيناً د دې نه خبر شى، نو ځکه زۀ دا مشوره درکوم چې مونږ دواړه مِلاو شُو چې په حالاتو باندې خبرې وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11539, 'Nehemiah 6:8', 'Nehemiah', 6, 8, '&nbsp;نو ما هغۀ له جواب ورولېږلو، ”تۀ چې څۀ وائې په هغۀ کښې هيڅ هم رښتيا نشته. دا هر څۀ تا د خپل ځان نه جوړ کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11540, 'Nehemiah 6:9', 'Nehemiah', 6, 9, '&nbsp;د هغوئ دا کوشش وو چې مونږ ويروى چې کار بند کړُو. خو ما دُعا وکړه، ”خُدايه پاکه، ما له طاقت راکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11541, 'Nehemiah 6:10', 'Nehemiah', 6, 10, '&nbsp;په هغه وخت زۀ د مهيطب‌اېل نمسى او د دلاياه زوئ سمعياه سره مِلاوېدو له لاړم، چې هغه د دې قابل نۀ وو چې د خپل کور نه لاړ شى. هغۀ ما ته ووئيل، ”زۀ او تۀ به لاړ شُو او د خُدائ پاک د کور په مقدس ځائ کښې به دواړه پټ شُو او دروازې به تالا کړُو، ځکه چې هغوئ ستا د وژلو دپاره راروان دى. نو هغوئ به ستا د وژلو دپاره د شپې راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11542, 'Nehemiah 6:11', 'Nehemiah', 6, 11, '&nbsp;ما په جواب کښې ورته ووئيل، ”زۀ داسې سړے نۀ يم چې وتښتم او پټ شم. ستا خيال دا دے څۀ چې زۀ به د خپل ژوند د بچ کولو دپاره د خُدائ پاک په کور کښې پټېږم؟ زۀ به داسې نۀ کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11543, 'Nehemiah 6:12', 'Nehemiah', 6, 12, '&nbsp;کله چې ما په دې باندې سوچ وکړو، نو ما ته پته ولګېده چې خُدائ پاک د سمعياه سره خبرې نۀ دى کړې، خو طوبياه او سنبلط هغۀ له د دې دپاره رشوت ورکړے دے چې ما له دا خبردارے راکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11544, 'Nehemiah 6:13', 'Nehemiah', 6, 13, '&nbsp;هغوئ هغۀ له د دې دپاره پېسې ورکړې وې چې ما ويروى او زۀ ګناه وکړم، نو چې هغوئ زما شُهرت خراب کړى او ما سپک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11545, 'Nehemiah 6:14', 'Nehemiah', 6, 14, '&nbsp;ما دُعا وکړه، ”خُدايه پاکه، چې طوبياه او سنبلط څۀ کړى دى هغه ياد ساته او سزا ورکړه. هغه ښځه نوعيدياه او نور ټول پېغمبران ياد ساته چا چې زما د يرولو کوشش کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11546, 'Nehemiah 6:15', 'Nehemiah', 6, 15, '&nbsp;د کار دوه پنځوسمې ورځې نه پس د الول د مياشتې په پينځويشتمه ورځ ټول دېوال ختم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11547, 'Nehemiah 6:16', 'Nehemiah', 6, 16, '&nbsp;کله چې په ګېرچاپېره مُلکونو کښې زمونږ دشمنان د دې نه خبر شول، نو هغوئ ويرېدل او خپل ځانونه ورته کمزورى ښکاره شول، ځکه چې هغوئ ته پته وه چې دا کار د خُدائ پاک د مدد سره شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11548, 'Nehemiah 6:17', 'Nehemiah', 6, 17, '&nbsp;په دې ټول وخت کښې د يهوديانو مشرانو او طوبياه يو بل ته ډېر خطونه لېږل رالېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11549, 'Nehemiah 6:18', 'Nehemiah', 6, 18, '&nbsp;په يهوداه کښې ډېرو خلقو د طوبياه ملګرتيا ځکه کوله چې د هغۀ سخر د ارخ زوئ سکانياه يهودى وو. د دې نه علاوه، د هغۀ زوئ يهوحنان د برکياه د زوئ د مسلام لور وادۀ کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11550, 'Nehemiah 6:19', 'Nehemiah', 6, 19, '&nbsp;طوبياه چې کوم ښۀ کارونه کړى وُو نو خلقو به د هغې ټولو په حقله زما په وړاندې خبرې کولې او ما چې څۀ وئيل نو هغه به يې طوبياه ته وئيل. او هغۀ زما د يرولو دپاره خطونه رالېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11551, 'Nehemiah 7:1', 'Nehemiah', 7, 1, '&nbsp;نو دېوال بيا جوړ شو، ټولې دروازې په خپلو ځايونو کښې ولګولے شوې او څوکيداران، حمد ويونکى او ليويان مقرر کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11552, 'Nehemiah 7:2', 'Nehemiah', 7, 2, '&nbsp;ما دوه سړى د يروشلم په ښار باندې مشران مقرر کړل، هغه زما ورور حنانى او د قلعه مشر آفسر حننياه وُو. حننياه اعتمادى سړے وو او هغه د نورو نه زيات د خُدائ پاک نه يرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11553, 'Nehemiah 7:3', 'Nehemiah', 7, 3, '&nbsp;ما هغوئ ته ووئيل، ”ترڅو پورې چې نمر تود شوے نۀ وى نو د يروشلم دروازې به نۀ کولاووئ. په کوم وخت کښې چې څوکيداران په ماښام کښې چهټى کوى نو هغوئ دې دروازې بندوى او اړمونه دې ورته واچوى. ما هغوئ ته دا هم ووئيل چې د يروشلم د اوسېدونکو خلقو نه يو څو څوکيداران مقرر کړئ چې څۀ کسانو ته په کښې خاص ځايونه حواله شى او نور دې د خپلو کورونو نه ګېرچاپېره ګشت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11554, 'Nehemiah 7:4', 'Nehemiah', 7, 4, '&nbsp;يروشلم يو لوئ ښار وو، خو ډېر خلق په کښې نۀ اوسېدل او ډېر کورونه په کښې نۀ وُو جوړ شوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11555, 'Nehemiah 7:5', 'Nehemiah', 7, 5, '&nbsp;خُدائ پاک دا خيال زما په زړۀ کښې واچولو چې دا خلق، د هغوئ مشران او آفسران راغونډ کړم او د هغوئ نسب‌نامه وګورم. ما د هغه خلقو حِساب کِتاب پېدا کړو کوم چې اول د جلاوطنۍ نه راواپس شوى وُو او ما ته چې کوم معلومات مِلاو شول هغه دا دى:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11556, 'Nehemiah 7:6', 'Nehemiah', 7, 6, '&nbsp;ډېر جلاوطن شوى کسان د بابل صُوبې نه لاړل او يروشلم او يهوداه ته راواپس شول، هر يو خپل ښار ته راغلو. د هغوئ خاندان په بابل کښې د جلاوطنۍ په دوران کښې د هغه وخت نه اوسېدې چې نبوکدنضر بادشاه هغوئ هلته قېديان بوتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11557, 'Nehemiah 7:7', 'Nehemiah', 7, 7, '&nbsp;د هغوئ مشران دا وُو، زرُبابل، يشوَع، نحمياه، عزرياه، رعمياه، نحمانى، مردکى، بِلشان، مِسفرت، بِګوئ، نحُوم او بعنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11558, 'Nehemiah 7:60', 'Nehemiah', 7, 60, '&nbsp;د خُدائ پاک د کور د خِدمتګارانو اولاد او د سليمان د هغه نوکرانو شمېر اتۀ کم څلور سوه وو کوم چې د جلاوطنۍ نه راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11559, 'Nehemiah 7:65', 'Nehemiah', 7, 65, '&nbsp;يهودى حکمران هغوئ ته وئيلى وُو چې هغوئ تر هغې پورې خُدائ پاک ته پېش کړے شوے خوراک نۀ شى خوړلے چې ترڅو پورې اِمام اُوريم او تميم نۀ وى استعمال کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11560, 'Nehemiah 7:73', 'Nehemiah', 7, 73, '&nbsp;اِمامان، ليويان، څوکيداران، سندرغاړى، او څۀ عام خلق، د خُدائ پاک د کور خِدمتګاران، او ټول بنى اِسرائيليان په وړو ښارونو او د يهوداه په ښارونو کښې دېره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11561, 'Nehemiah 8:1', 'Nehemiah', 8, 1, '&nbsp;تر اوومې مياشتې پورې ټول بنى اِسرائيل په خپلو ښارونو کښې دېره شول. د دې مياشتې په اوله ورځ هغوئ ټول په يروشلم کښې د اوبو دروازې سره دننه د جرګې په ځائ کښې راغونډ شول. هغوئ عزرا عالِم ته ووئيل چې د موسىٰ د شريعت هغه کِتاب راوړى کوم چې مالِک خُدائ بنى اِسرائيلو له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11562, 'Nehemiah 8:2', 'Nehemiah', 8, 2, '&nbsp;نو عزرا د شريعت کِتاب هغه ځائ ته راوړو او دا د اوومې مياشت اوله ورځ وه چرته چې خلق راغونډ وُو. په هغوئ کښې سړى، ښځې او هغه ماشومان وُو چې د هغوئ عُمر دومره وو چې په دې باندې پوهېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11563, 'Nehemiah 8:3', 'Nehemiah', 8, 3, '&nbsp;هلته د دروازې سره د جرګې په ځائ کښې هغۀ ورته د سحر وختى نه واخله تر غرمې پورې شريعت لوستلو او هغوئ ټولو ورته په توجو سره غوږ اېښے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11564, 'Nehemiah 8:4', 'Nehemiah', 8, 4, '&nbsp;عزرا د لرګى د پايو په ممبر باندې ولاړ وو کوم چې د دې موقعې دپاره جوړ شوے وو. دا کسان د هغۀ ښى طرف ته ولاړ وُو، متتياه، سمع، عناياه، اورِياه، خِلقياه، او معسياه، او دا کسان يې ګس طرف ته ولاړ وُو، فداياه، ميسائيل، مُلکياه، حاشوم، حسبدانه، زکرياه او مسلام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11565, 'Nehemiah 8:5', 'Nehemiah', 8, 5, '&nbsp;عزرا په داسې اوچت ځائ باندې ولاړ وو چې ټولو خلقو ليدلے شو. چې څنګه هغۀ کِتاب کولاو کړو، نو هغوئ ټول ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11566, 'Nehemiah 8:6', 'Nehemiah', 8, 6, '&nbsp;عزرا وفرمائيل، ”د مالِک خُدائ د لوئ خُدائ پاک ثناء صِفت دې وى.“ نو ټولو خلقو خپل لاسونه اوچت کړل او وې وئيل، ”آمين، آمين.“ هغوئ په عبادت کښې ټيټ شول او په زمکه يې مالِک خُدائ ته سجده ولګوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11567, 'Nehemiah 8:7', 'Nehemiah', 8, 7, '&nbsp;بيا هغوئ په خپلو خپلو ځايونو باندې ودرېدل، او دې ليويانو ورته د شريعت تشريح وکړه، يشوَع، بانى، سربياه، يمين، عقوب، سبتى، هودياه، معسياه، قليتاه، عزرياه، يوزبد، حنان او فلاياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11568, 'Nehemiah 8:8', 'Nehemiah', 8, 8, '&nbsp;هغوئ ورته د خُدائ پاک شريعت ولوستلو او د دې تشريح يې ورته وکړه، چې خلق يې په مطلب باندې پوهه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11569, 'Nehemiah 8:9', 'Nehemiah', 8, 9, '&nbsp;کله چې خلقو ته پته ولګېده چې د شريعت مطالبه څۀ ده، نو هغوئ په ژړا شروع وکړه. نو نحمياه چې حکمران وو، عزرا چې د شريعت اِمام او عالِم وو او هغه ليويانو چې د شريعت تشريح يې کوله هغوئ ټولو هغه خلقو ته وفرمائيل چې، ”دا ورځ د مالِک خُدائ ستاسو د خُدائ پاک دپاره مقدسه ده، نو تاسو له نۀ دى په کار چې غم يا ژړا وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11570, 'Nehemiah 8:10', 'Nehemiah', 8, 10, '&nbsp;نو د خوراک څښاک دپاره خپلو کورونو ته لاړ شئ او په خپل خوراک او ميو کښې د هغه خلقو هم حِصه وکړئ چې چا سره دا څيزونه نۀ وى. نن زمونږ د مالِک خُدائ دپاره يوه مقدسه ورځ ده، نو مۀ خفه کېږئ. د مالِک خُدائ خوشحالى ستاسو د طاقت بنياد دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11571, 'Nehemiah 8:11', 'Nehemiah', 8, 11, '&nbsp;نو ليويانو خلق قلارول او ورته يې وئيل چې په داسې مقدسه ورځ خفګان مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11572, 'Nehemiah 8:12', 'Nehemiah', 8, 12, '&nbsp;نو ټول خلق خپلو کورونو ته لاړل او په خوشحالۍ سره يې خوراک څښاک وکړو او په دې خوراک څښاک کښې يې د نورو خلقو حِصه هم وکړه، ځکه چې هغوئ د خُدائ پاک کلام اورېدلے وو او په هغې پوهه شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11573, 'Nehemiah 8:13', 'Nehemiah', 8, 13, '&nbsp;په ورپسې ورځ د ډلو مشران چې د هغوئ اِمامان او ليويان هم ورسره وُو، هغوئ عزرا عالِم له لاړل چې د شريعت حُکمونه زده کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11574, 'Nehemiah 8:14', 'Nehemiah', 8, 14, '&nbsp;هغوئ ته دا پته ولګېده چې هغه شريعت دا حُکم کوى کوم چې مالِک خُدائ د موسىٰ په ذريعه ورکړے وو چې د جونګړو د اختر په دوران کښې دې بنى اِسرائيليان په جونګړو کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11575, 'Nehemiah 8:15', 'Nehemiah', 8, 15, '&nbsp;نو هغوئ ورته دا اصُول وښودل او ټول يې يروشلم او نورو وړو او غټو ښارونو ته ولېږل، ”غرونو ته لاړ شئ او د نختر، د زيتُونو، د کجورو او د هغه نورو ونو لښتې راؤړئ چې سورے جوړوى، چې د هغه اصُولو په مطابق جونګړې جوړې کړُو چې د شريعت په کِتاب کښې ليکلے شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11576, 'Nehemiah 8:16', 'Nehemiah', 8, 16, '&nbsp;نو خلقو څانګې راوړې او د خپلو کورونو په چتونو، په خپلو صحنونو کښې، د خُدائ پاک د کور په دربار کښې او د اِفرائيم دروازې او د اوبو دروازې سره د جرګې په عوامى ځايونو کښې يې جونګړې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11577, 'Nehemiah 8:17', 'Nehemiah', 8, 17, '&nbsp;هغه ټول خلق کوم چې د جلاوطنۍ نه واپس راغلى وُو هغوئ جونګړې جوړې کړې او په هغې کښې اوسېدل او هر يو کس جذباتى او خوشحاله وو. د نون زوئ يشوَع د وخت نه پس داسې نۀ وُو شوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11578, 'Nehemiah 8:18', 'Nehemiah', 8, 18, '&nbsp;د اختر د وړومبۍ ورځې نه واخله تر آخرى ورځې پورې هغوئ هره ورځ د خُدائ پاک د شريعت يوه حِصه لوستله. هغوئ اووۀ ورځې دا اختر وکړو او په اتمه ورځ د اختر د ختمېدو اجتماع وشوه، هم هغه شان لکه څنګه چې په شريعت کښې لازمى شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11579, 'Nehemiah 9:1', 'Nehemiah', 9, 1, '&nbsp;هم د هغه مياشتې په څليريشتمه ورځ بنى اِسرائيل راغونډ شول، او روژه يې نيولې وه، د ټاټ جامې يې اغوستې وې او په خپلو سرونو باندې يې خاورې اچولې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11580, 'Nehemiah 9:2', 'Nehemiah', 9, 2, '&nbsp;ټولو بنى اِسرائيلو د پردى وطن د خلقو نه ځانونه جدا کړى وُو. بيا هغوئ ودرېدل او د هغه ګناهونو اِقرار شروع کړو کوم چې هغوئ او د هغوئ پلار نيکۀ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11581, 'Nehemiah 9:3', 'Nehemiah', 9, 3, '&nbsp;تقريباً درې ګينټې هغوئ ولاړ وُو او د مالِک خُدائ د هغوئ د خُدائ پاک قانون ورته ولوستلے شو او ورپسې درې ګينټې هغوئ د خپلو ګناهونو اِقرار وکړو او د مالِک خُدائ د خپل خُدائ پاک عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11582, 'Nehemiah 9:4', 'Nehemiah', 9, 4, '&nbsp;هلته د ليويانو په ممبر باندې دا کسان ولاړ وُو، يشوَع، بانى، قدمى‌اېل، شبنياه، بُنى، سربياه، بانى او کنعنياه. هغوئ مالِک خُدائ خپل خُدائ پاک ته په چغو چغو وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11583, 'Nehemiah 9:5', 'Nehemiah', 9, 5, '&nbsp;د ليويانو دې مشرانو خلقو ته آواز وکړو، يشوَع، قدمى‌اېل، بانى، حسبنياه، سربياه، هودياه، شبنياه او فتحياه، او هغوئ ووئيل: ”پاڅئ او د مالِک خُدائ ستاسو د خُدائ پاک ثناء صِفت وکړئ، د هغۀ ثناء صِفت همېشه همېشه کوئ. د هغۀ د شان شوکت والا نوم دې برکتناک وى، دا دې د ټولو صِفتونو او برکتونو نه اوچت وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11584, 'Nehemiah 9:6', 'Nehemiah', 9, 6, '&nbsp;او بيا بنى اِسرائيلو دا دُعا وکړه، ”مالِکه خُدايه، يواځې تۀ مالِک خُدائ يې، تا آسمانونه او د آسمان ستورى جوړ کړى دى. تا زمکه او سمندر او په دې کښې هر څۀ جوړ کړى دى، تا هر څيز له ساه ورکړې ده. آسمانى مخلوق تا ته سجده کوى او ستا عبادت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11585, 'Nehemiah 9:7', 'Nehemiah', 9, 7, '&nbsp;مالِکه خُدايه، خُدايه پاکه، تا ابرام غوره کړو، او تا هغه د بابل ښار اُور نه راوويستلو، تا د هغۀ نوم اِبراهيم ته بدل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11586, 'Nehemiah 9:8', 'Nehemiah', 9, 8, '&nbsp;تا ته پته ولګېده چې هغه ستا وفادار دے، نو تا د هغۀ سره يو لوظ وکړو. دا لوظ چې د کنعانيانو مُلک به ورکوې، د حِتيانو او اموريانو مُلک، د فرزيانو، يبوسيانو او جرجاسيانو مُلک، چې هغه به داسې يو مُلک وى چې د هغۀ اولاد په کښې اوسيږى. تا خپله وعده ځکه پوره کړه چې تۀ وفادار يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11587, 'Nehemiah 9:9', 'Nehemiah', 9, 9, '&nbsp;تا وکتل چې زمونږ پلار نيکۀ په مِصر کښې څومره کړېدلى وُو، تا د بحرِقُلزم سره د هغوئ د مدد دپاره فرياد واورېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11588, 'Nehemiah 9:10', 'Nehemiah', 9, 10, '&nbsp;تا د فِرعون خِلاف عجيبه معجزې وکړې، دا معجزې د هغۀ آفسرانو او د هغه مُلک د خلقو خِلاف وې، ځکه چې تا ته پته وه چې هغوئ ستا په خلقو باندې څومره ظلم کولو. تا هغه شُهرت حاصل کړو چې تر ننه پورې يې لرې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11589, 'Nehemiah 9:11', 'Nehemiah', 9, 11, '&nbsp;تا د خپلو خلقو دپاره په درياب کښې لار جوړه کړه او هغوئ دې په اوچه زمکه باندې تېر کړل. او چې څوک ورپسې وُو نو هغوئ په ژورو اوبو کښې ډُوب شول، داسې لکه چې يو غضبناک سمندر کښې کاڼے ډوبيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11590, 'Nehemiah 9:12', 'Nehemiah', 9, 12, '&nbsp;د وريځې د ستنې په ذريعه تا هغوئ د ورځې په وخت بوتلل، او د شپې په وخت دې د اور د ستنې په ذريعه د هغوئ په لار کښې رڼا جوړوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11591, 'Nehemiah 9:13', 'Nehemiah', 9, 13, '&nbsp;د سينا غر سره تۀ د آسمان نه راکوز شوې، تا د خپلو خلقو سره خبرې وکړې او هغوئ ته دې اِنصاف قانون او ښۀ اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11592, 'Nehemiah 9:14', 'Nehemiah', 9, 14, '&nbsp;تا هغوئ ته وښودل چې ستا د سبت ورځ مقدسه وګڼى، او تا د خپل خِدمت کوونکى موسىٰ په ذريعه هغوئ له خپل قانون ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11593, 'Nehemiah 9:15', 'Nehemiah', 9, 15, '&nbsp;کله چې هغوئ اوږى وُو، نو تا هغوئ له د آسمان نه روټۍ ورکړه، او چې کله هغوئ تږى وُو نو تا د يو کاڼى نه هغوئ له اوبۀ ورکړې. تا هغوئ ته ووئيل چې هغه مُلک قبضه کړئ د کوم چې تا هغوئ له د ورکولو وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11594, 'Nehemiah 9:16', 'Nehemiah', 9, 16, '&nbsp;خو زمونږ پلار نيکۀ مغروره او ضديان شول او ستا د حُکمونو د منلو نه يې اِنکار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11595, 'Nehemiah 9:17', 'Nehemiah', 9, 17, '&nbsp;هغوئ نافرمانى وکړه، تا چې کومې معجزې کړې وې هغه يې هېرې کړې. په خپله سرکشۍ کښې هغوئ يو مشر خوښ کړو چې د مِصر غلامۍ له يې واپس بوځى. خو تۀ بخښونکے خُدائ پاک يې، تۀ مهربان او مينه کوونکے يې، زر نۀ غصه کېږې. ستا رحم لوئ دے، تا هغوئ پرې نۀ ښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11596, 'Nehemiah 9:18', 'Nehemiah', 9, 18, '&nbsp;هغوئ د سخى په شکل کښې يو بُت جوړ کړو او وې وئيل چې دا هغه خُدائ دے چې تاسو يې د مِصر نه راوويستلئ. مالِکه خُدايه، هغوئ ستا څومره بې‌عزتى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11597, 'Nehemiah 9:19', 'Nehemiah', 9, 19, '&nbsp;خو هغوئ دې هلته په صحرا کښې پرې نۀ ښودل، ځکه چې ستا رحم ډېر لوئ دے. تا نۀ د وريځې او نۀ د اور ستن لرې کړه چې د شپې او ورځې يې ورته لار ښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11598, 'Nehemiah 9:20', 'Nehemiah', 9, 20, '&nbsp;تا د خپل نېک روح په ذريعه د هغوئ لارښودنه وکړه، تا هغوئ له د خوراک دپاره من ورکولو او د څښلو دپاره دې اوبۀ ورکولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11599, 'Nehemiah 9:21', 'Nehemiah', 9, 21, '&nbsp;په صحرا کښې په ټولو څلوېښتو کالو کښې چې هغوئ ته د څۀ ضرورت وو د هغې هر څۀ بندوبست دې ورله وکړو، د هغوئ جامې هيڅکله زړې نۀ شوې، او د هغوئ پښې ونۀ پړسېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11600, 'Nehemiah 9:22', 'Nehemiah', 9, 22, '&nbsp;په قومونو او بادشاهو فتح کولو کښې تا د هغوئ مدد کولو، او تا خپل خلق په هر ځائ کښې آباد کړل. هغوئ د حسبون مُلک فتح کړو، چرته چې سيحون بادشاهى کوله، او د بسن مُلک، چرته چې عوج بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');